INSERT INTO curriculum_nodes (id, slug, phase_id, order_index, title, subtitle, cs_foundation, ai_convergence, xp_reward, level_required, position_x, position_y, handbook_markdown, starter_code, test_suite, defense_prompts) VALUES
('node-9-16', 'phase-09-lesson-16-analytical-backpropagation-i-gradients-fo', 'module-4', 16, 'Lesson 4.16: Analytical Backpropagation I: Gradients for Linear Layers & Affine Transforms', 'Prerequisites: Lesson 9.7, Lesson 9.15', 'Prerequisites: Lesson 9.7, Lesson 9.15 | Subtopics: 6 items', 'Systems project application', 280, 10, 2310.0, 800.0, '# Lesson 9.16: Analytical Backpropagation I: Gradients for Linear Layers & Affine Transforms

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.7, Lesson 9.15
- **Subtopics**:
  - `9.16.1` The scalar-by-matrix derivative: conventions, dimensions matching, and chain rule application
  - `9.16.2` Forward pass of linear layer: $Y = X W + b$ with shapes $X \in \mathbb{R}^{B \times D}$, $W \in \mathbb{R}^{D \times M}$, $b \in \mathbb{R}^{1 \times M}$
  - `9.16.3` Derivation of weight gradient: $\frac{\partial L}{\partial W} = X^T \frac{\partial L}{\partial Y}$ (dimensions $(D \times B) \times (B \times M) = (D \times M)$)
  - `9.16.4` Derivation of input gradient: $\frac{\partial L}{\partial X} = \frac{\partial L}{\partial Y} W^T$ (dimensions $(B \times M) \times (M \times D) = (B \times D)$)
  - `9.16.5` Derivation of bias gradient: $\frac{\partial L}{\partial b} = \sum_{i=1}^B \frac{\partial L}{\partial Y_{i,:}}$ (summing over batch dimension)
  - `9.16.6` Memory management: caching input activations $X$ and weights $W$ during forward pass for backward computation
- **Key Failure Modes & Edge Cases**: Transposing matrices incorrectly in backpropagation formulas, producing dimension mismatches or computing invalid gradients.
- **Verification & Mastery Check**: Derive and hand-code the forward and backward passes for a dense linear layer in NumPy; verify gradients via finite differences.
- **Project Application**: GradFlow: Dense Linear layer with exact analytical backprop.', '{"solution.py": "# Phase 9 // Lesson 9.16: Analytical Backpropagation I: Gradients for Linear Layers & Affine Transforms\n\ndef solve():\n    \"\"\"\n    Verification: Derive and hand-code the forward and backward passes for a dense linear layer in NumPy; verify gradi\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.16", "subtopics_count": 6, "verification_criteria": "Derive and hand-code the forward and backward passes for a dense linear layer in NumPy; verify gradients via finite differences.", "subtopics": ["9.16.1 The scalar-by-matrix derivative: conventions, dimensions matching, and chain rule application", "9.16.2 Forward pass of linear layer: $Y = X W + b$ with shapes $X \\in \\mathbb{R}^{B \\times D}$, $W \\in \\mathbb{R}^{D \\times M}$, $b \\in \\mathbb{R}^{1 \\times M}$", "9.16.3 Derivation of weight gradient: $\\frac{\\partial L}{\\partial W} = X^T \\frac{\\partial L}{\\partial Y}$ (dimensions $(D \\times B) \\times (B \\times M) = (D \\times M)$)", "9.16.4 Derivation of input gradient: $\\frac{\\partial L}{\\partial X} = \\frac{\\partial L}{\\partial Y} W^T$ (dimensions $(B \\times M) \\times (M \\times D) = (B \\times D)$)", "9.16.5 Derivation of bias gradient: $\\frac{\\partial L}{\\partial b} = \\sum_{i=1}^B \\frac{\\partial L}{\\partial Y_{i,:}}$ (summing over batch dimension)", "9.16.6 Memory management: caching input activations $X$ and weights $W$ during forward pass for backward computation"]}'::jsonb, '["Explain how this implementation prevents: Transposing matrices incorrectly in backpropagation formulas, producing dimension mismatches or computing invalid gradie", "How does Analytical Backpropagation I: Gradients for Linear Layers & Affine Transforms scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-17', 'phase-09-lesson-17-analytical-backpropagation-ii-end-to-end-', 'module-4', 17, 'Lesson 4.17: Analytical Backpropagation II: End-to-End 3-Layer Network by Hand', 'Prerequisites: Lesson 9.16', 'Prerequisites: Lesson 9.16 | Subtopics: 6 items', 'Systems project application', 280, 10, 2370.0, 850.0, '# Lesson 9.17: Analytical Backpropagation II: End-to-End 3-Layer Network by Hand

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.16
- **Subtopics**:
  - `9.17.1` End-to-end forward architecture: $Z_1 = X W_1 + b_1$, $A_1 = \text{ReLU}(Z_1)$, $Z_2 = A_1 W_2 + b_2$, $\hat{Y} = \text{Softmax}(Z_2)$
  - `9.17.2` Loss calculation: $L = \text{CrossEntropy}(\hat{Y}, Y)$
  - `9.17.3` Step 1 backward: output logit gradient $\delta_2 = \frac{\partial L}{\partial Z_2} = \hat{Y} - Y$
  - `9.17.4` Step 2 backward: parameter gradients $\frac{\partial L}{\partial W_2} = A_1^T \delta_2$, $\frac{\partial L}{\partial b_2} = \text{sum}(\delta_2, \text{axis}=0)$
  - `9.17.5` Step 3 backward: hidden activation gradient $\frac{\partial L}{\partial A_1} = \delta_2 W_2^T$
  - `9.17.6` Step 4 backward: ReLU gate gradient $\delta_1 = \frac{\partial L}{\partial Z_1} = \frac{\partial L}{\partial A_1} \odot \mathbb{I}(Z_1 > 0)$, followed by $W_1, b_1$ gradients
- **Key Failure Modes & Edge Cases**: Computing ReLU backward gradient using post-activation values $A_1$ rather than pre-activation $Z_1$ when Leaky ReLU is introduced.
- **Verification & Mastery Check**: Implement a 3-layer neural network from scratch in NumPy with 100% manual backpropagation; train it to 98% accuracy on MNIST.
- **Project Application**: GradFlow: Fully verified manual MLP reference implementation.', '{"solution.py": "# Phase 9 // Lesson 9.17: Analytical Backpropagation II: End-to-End 3-Layer Network by Hand\n\ndef solve():\n    \"\"\"\n    Verification: Implement a 3-layer neural network from scratch in NumPy with 100% manual backpropagation; train it \n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.17", "subtopics_count": 6, "verification_criteria": "Implement a 3-layer neural network from scratch in NumPy with 100% manual backpropagation; train it to 98% accuracy on MNIST.", "subtopics": ["9.17.1 End-to-end forward architecture: $Z_1 = X W_1 + b_1$, $A_1 = \\text{ReLU}(Z_1)$, $Z_2 = A_1 W_2 + b_2$, $\\hat{Y} = \\text{Softmax}(Z_2)$", "9.17.2 Loss calculation: $L = \\text{CrossEntropy}(\\hat{Y}, Y)$", "9.17.3 Step 1 backward: output logit gradient $\\delta_2 = \\frac{\\partial L}{\\partial Z_2} = \\hat{Y} - Y$", "9.17.4 Step 2 backward: parameter gradients $\\frac{\\partial L}{\\partial W_2} = A_1^T \\delta_2$, $\\frac{\\partial L}{\\partial b_2} = \\text{sum}(\\delta_2, \\text{axis}=0)$", "9.17.5 Step 3 backward: hidden activation gradient $\\frac{\\partial L}{\\partial A_1} = \\delta_2 W_2^T$", "9.17.6 Step 4 backward: ReLU gate gradient $\\delta_1 = \\frac{\\partial L}{\\partial Z_1} = \\frac{\\partial L}{\\partial A_1} \\odot \\mathbb{I}(Z_1 > 0)$, followed by $W_1, b_1$ gradients"]}'::jsonb, '["Explain how this implementation prevents: Computing ReLU backward gradient using post-activation values $A_1$ rather than pre-activation $Z_1$ when Leaky ReLU is ", "How does Analytical Backpropagation II: End-to-End 3-Layer Network by Hand scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-18', 'phase-09-lesson-18-numerical-gradient-checking-gradcheck-fin', 'module-4', 18, 'Lesson 4.18: Numerical Gradient Checking (GradCheck) & Finite Differences', 'Prerequisites: Lesson 9.7, Lesson 9.17', 'Prerequisites: Lesson 9.7, Lesson 9.17 | Subtopics: 6 items', 'Systems project application', 280, 10, 2250.0, 900.0, '# Lesson 9.18: Numerical Gradient Checking (GradCheck) & Finite Differences

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.7, Lesson 9.17
- **Subtopics**:
  - `9.18.1` Why gradient checking is essential: silent bugs in analytical backprop allowing networks to learn partially while degrading performance
  - `9.18.2` Finite difference approximations: Forward difference ($\frac{f(\theta + \epsilon) - f(\theta)}{\epsilon}$, error $O(\epsilon)$)
  - `9.18.3` Centered difference approximation: $\frac{f(\theta + \epsilon) - f(\theta - \epsilon)}{2\epsilon}$, error $O(\epsilon^2)$
  - `9.18.4` Choosing the perturbation size: why $\epsilon \approx 10^{-7}$ balances truncation error and floating-point cancellation error
  - `9.18.5` Relative error metric: $\frac{\|\nabla_{analytical} - \nabla_{numerical}\|_2}{\|\nabla_{analytical}\|_2 + \|\nabla_{numerical}\|_2 + 10^{-15}}$
  - `9.18.6` Failure triage: interpreting relative errors ($<10^{-7}$ perfect, $>10^{-2}$ major bug in analytical backprop)
- **Key Failure Modes & Edge Cases**: Using forward difference instead of centered difference, leading to false-positive gradient bug warnings.
- **Verification & Mastery Check**: Build a universal `grad_check` utility function verifying arbitrary tensor layers against centered finite differences.
- **Project Application**: GradFlow: Universal gradient checking verification suite.', '{"solution.py": "# Phase 9 // Lesson 9.18: Numerical Gradient Checking (GradCheck) & Finite Differences\n\ndef solve():\n    \"\"\"\n    Verification: Build a universal `grad_check` utility function verifying arbitrary tensor layers against centered f\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.18", "subtopics_count": 6, "verification_criteria": "Build a universal `grad_check` utility function verifying arbitrary tensor layers against centered finite differences.", "subtopics": ["9.18.1 Why gradient checking is essential: silent bugs in analytical backprop allowing networks to learn partially while degrading performance", "9.18.2 Finite difference approximations: Forward difference ($\\frac{f(\\theta + \\epsilon) - f(\\theta)}{\\epsilon}$, error $O(\\epsilon)$)", "9.18.3 Centered difference approximation: $\\frac{f(\\theta + \\epsilon) - f(\\theta - \\epsilon)}{2\\epsilon}$, error $O(\\epsilon^2)$", "9.18.4 Choosing the perturbation size: why $\\epsilon \\approx 10^{-7}$ balances truncation error and floating-point cancellation error", "9.18.5 Relative error metric: $\\frac{\\|\\nabla_{analytical} - \\nabla_{numerical}\\|_2}{\\|\\nabla_{analytical}\\|_2 + \\|\\nabla_{numerical}\\|_2 + 10^{-15}}$", "9.18.6 Failure triage: interpreting relative errors ($<10^{-7}$ perfect, $>10^{-2}$ major bug in analytical backprop)"]}'::jsonb, '["Explain how this implementation prevents: Using forward difference instead of centered difference, leading to false-positive gradient bug warnings.", "How does Numerical Gradient Checking (GradCheck) & Finite Differences scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-19', 'phase-09-lesson-19-weight-initialization-dynamics-vanishing-', 'module-4', 19, 'Lesson 4.19: Weight Initialization Dynamics: Vanishing/Exploding Gradients & He/Xavier', 'Prerequisites: Lesson 9.10, Lesson 9.16', 'Prerequisites: Lesson 9.10, Lesson 9.16 | Subtopics: 6 items', 'Systems project application', 280, 10, 2310.0, 950.0, '# Lesson 9.19: Weight Initialization Dynamics: Vanishing/Exploding Gradients & He/Xavier

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.10, Lesson 9.16
- **Subtopics**:
  - `9.19.1` The initialization problem: zero initialization symmetry breaking failure, too small (vanishing), too large (exploding)
  - `9.19.2` Variance propagation through layers: deriving $\text{Var}(y) = n \cdot \text{Var}(w) \cdot \text{Var}(x)$ under zero-mean inputs
  - `9.19.3` Xavier (Glorot) Initialization: preserving variance across forward and backward passes for tanh/sigmoid: $W \sim \mathcal{N}\left(0, \frac{2}{n_{in} + n_{out}}\right)$
  - `9.19.4` He (Kaiming) Initialization: accounting for half-rectification in ReLU activations: $W \sim \mathcal{N}\left(0, \frac{2}{n_{in}}\right)$
  - `9.19.5` LeCun Initialization: optimal scaling for SELU self-normalizing networks
  - `9.19.6` Modern LLM initialization: scaling residual projection weights by $\frac{1}{\sqrt{2 \times N_{layers}}}$ to stabilize deep Transformer training
- **Key Failure Modes & Edge Cases**: Initializing weights with standard normal distribution $\mathcal{N}(0, 1)$, causing activations to explode to infinity within 6 layers.
- **Verification & Mastery Check**: Simulate activation and gradient variance through 50 layers with different initializations; prove He initialization prevents collapse.
- **Project Application**: GradFlow: Initializer module (He, Xavier, Normal, Uniform).', '{"solution.py": "# Phase 9 // Lesson 9.19: Weight Initialization Dynamics: Vanishing/Exploding Gradients & He/Xavier\n\ndef solve():\n    \"\"\"\n    Verification: Simulate activation and gradient variance through 50 layers with different initializations; prove He\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.19", "subtopics_count": 6, "verification_criteria": "Simulate activation and gradient variance through 50 layers with different initializations; prove He initialization prevents collapse.", "subtopics": ["9.19.1 The initialization problem: zero initialization symmetry breaking failure, too small (vanishing), too large (exploding)", "9.19.2 Variance propagation through layers: deriving $\\text{Var}(y) = n \\cdot \\text{Var}(w) \\cdot \\text{Var}(x)$ under zero-mean inputs", "9.19.3 Xavier (Glorot) Initialization: preserving variance across forward and backward passes for tanh/sigmoid: $W \\sim \\mathcal{N}\\left(0, \\frac{2}{n_{in} + n_{out}}\\right)$", "9.19.4 He (Kaiming) Initialization: accounting for half-rectification in ReLU activations: $W \\sim \\mathcal{N}\\left(0, \\frac{2}{n_{in}}\\right)$", "9.19.5 LeCun Initialization: optimal scaling for SELU self-normalizing networks", "9.19.6 Modern LLM initialization: scaling residual projection weights by $\\frac{1}{\\sqrt{2 \\times N_{layers}}}$ to stabilize deep Transformer training"]}'::jsonb, '["Explain how this implementation prevents: Initializing weights with standard normal distribution $\\mathcal{N}(0, 1)$, causing activations to explode to infinity w", "How does Weight Initialization Dynamics: Vanishing/Exploding Gradients & He/Xavier scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-20', 'phase-09-lesson-20-batch-normalization-layer-normalization-i', 'module-4', 20, 'Lesson 4.20: Batch Normalization & Layer Normalization Internals', 'Prerequisites: Lesson 9.10, Lesson 9.19', 'Prerequisites: Lesson 9.10, Lesson 9.19 | Subtopics: 6 items', 'Systems project application', 280, 10, 2370.0, 1000.0, '# Lesson 9.20: Batch Normalization & Layer Normalization Internals

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.10, Lesson 9.19
- **Subtopics**:
  - `9.20.1` Internal Covariate Shift hypothesis vs smoothing the optimization landscape: how normalization stabilizes loss surfaces
  - `9.20.2` Batch Normalization (BatchNorm): batch mean, batch variance, normalize, affine scale and shift ($\gamma \hat{x} + \beta$)
  - `9.20.3` Running statistics in BatchNorm: tracking running_mean and running_var via momentum for evaluation mode inference
  - `9.20.4` Failure modes of BatchNorm: small batch sizes, sequence modeling disparity, and training/eval mode mismatch bugs
  - `9.20.5` Layer Normalization (LayerNorm): normalizing across feature dimensions per sample independently of batch size
  - `9.20.6` Analytical backpropagation through LayerNorm: deriving gradients with respect to inputs, gamma, and beta
- **Key Failure Modes & Edge Cases**: Forgetting to switch BatchNorm from training mode to evaluation mode, producing catastrophic random predictions during production inference.
- **Verification & Mastery Check**: Implement LayerNorm and BatchNorm from scratch in NumPy, including both forward pass and complete analytical backward gradient passes.
- **Project Application**: TransformerLab: Pre-LayerNorm and RMSNorm layers.', '{"solution.py": "# Phase 9 // Lesson 9.20: Batch Normalization & Layer Normalization Internals\n\ndef solve():\n    \"\"\"\n    Verification: Implement LayerNorm and BatchNorm from scratch in NumPy, including both forward pass and complete an\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.20", "subtopics_count": 6, "verification_criteria": "Implement LayerNorm and BatchNorm from scratch in NumPy, including both forward pass and complete analytical backward gradient passes.", "subtopics": ["9.20.1 Internal Covariate Shift hypothesis vs smoothing the optimization landscape: how normalization stabilizes loss surfaces", "9.20.2 Batch Normalization (BatchNorm): batch mean, batch variance, normalize, affine scale and shift ($\\gamma \\hat{x} + \\beta$)", "9.20.3 Running statistics in BatchNorm: tracking running_mean and running_var via momentum for evaluation mode inference", "9.20.4 Failure modes of BatchNorm: small batch sizes, sequence modeling disparity, and training/eval mode mismatch bugs", "9.20.5 Layer Normalization (LayerNorm): normalizing across feature dimensions per sample independently of batch size", "9.20.6 Analytical backpropagation through LayerNorm: deriving gradients with respect to inputs, gamma, and beta"]}'::jsonb, '["Explain how this implementation prevents: Forgetting to switch BatchNorm from training mode to evaluation mode, producing catastrophic random predictions during p", "How does Batch Normalization & Layer Normalization Internals scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-21', 'phase-09-lesson-21-optimization-fundamentals-gradient-descen', 'module-4', 21, 'Lesson 4.21: Optimization Fundamentals: Gradient Descent & Stochastic Gradient Descent (SGD)', 'Prerequisites: Lesson 9.7, Lesson 9.16', 'Prerequisites: Lesson 9.7, Lesson 9.16 | Subtopics: 6 items', 'Systems project application', 280, 10, 2250.0, 1050.0, '# Lesson 9.21: Optimization Fundamentals: Gradient Descent & Stochastic Gradient Descent (SGD)

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.7, Lesson 9.16
- **Subtopics**:
  - `9.21.1` Optimization landscape: convex functions vs non-convex neural network loss surfaces, local minima, and saddle points
  - `9.21.2` Batch Gradient Descent (BGD): updating parameters over full dataset; stability vs extreme computational cost on large data
  - `9.21.3` Stochastic Gradient Descent (SGD): single-sample parameter updates; high variance, noisy gradient estimates, escaping saddle points
  - `9.21.4` Mini-Batch SGD: sweet spot balancing computational parallelism on GPUs with gradient estimation stability ($B=32, 64, 256$)
  - `9.21.5` Learning rate (step size $\eta$): divergence from overly high $\eta$, creeping stagnation from overly low $\eta$
  - `9.21.6` Ill-conditioned ravines: why standard SGD oscillates violently perpendicular to steep valley walls while making slow progress along the valley floor
- **Key Failure Modes & Edge Cases**: Using an excessively high learning rate causing loss to diverge to infinity/NaN within the first few parameter update steps.
- **Verification & Mastery Check**: Implement a modular Mini-Batch SGD optimizer in pure NumPy with batch generation, epoch looping, and loss tracking.
- **Project Application**: GradFlow: Base optimizer class and SGD implementation.', '{"solution.py": "# Phase 9 // Lesson 9.21: Optimization Fundamentals: Gradient Descent & Stochastic Gradient Descent (SGD)\n\ndef solve():\n    \"\"\"\n    Verification: Implement a modular Mini-Batch SGD optimizer in pure NumPy with batch generation, epoch looping, and\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.21", "subtopics_count": 6, "verification_criteria": "Implement a modular Mini-Batch SGD optimizer in pure NumPy with batch generation, epoch looping, and loss tracking.", "subtopics": ["9.21.1 Optimization landscape: convex functions vs non-convex neural network loss surfaces, local minima, and saddle points", "9.21.2 Batch Gradient Descent (BGD): updating parameters over full dataset; stability vs extreme computational cost on large data", "9.21.3 Stochastic Gradient Descent (SGD): single-sample parameter updates; high variance, noisy gradient estimates, escaping saddle points", "9.21.4 Mini-Batch SGD: sweet spot balancing computational parallelism on GPUs with gradient estimation stability ($B=32, 64, 256$)", "9.21.5 Learning rate (step size $\\eta$): divergence from overly high $\\eta$, creeping stagnation from overly low $\\eta$", "9.21.6 Ill-conditioned ravines: why standard SGD oscillates violently perpendicular to steep valley walls while making slow progress along the valley floor"]}'::jsonb, '["Explain how this implementation prevents: Using an excessively high learning rate causing loss to diverge to infinity/NaN within the first few parameter update st", "How does Optimization Fundamentals: Gradient Descent & Stochastic Gradient Descent (SGD) scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-22', 'phase-09-lesson-22-advanced-optimizers-momentum-nesterov-rms', 'module-4', 22, 'Lesson 4.22: Advanced Optimizers: Momentum, Nesterov, RMSprop & AdamW', 'Prerequisites: Lesson 9.21', 'Prerequisites: Lesson 9.21 | Subtopics: 6 items', 'Systems project application', 280, 10, 2310.0, 1100.0, '# Lesson 9.22: Advanced Optimizers: Momentum, Nesterov, RMSprop & AdamW

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.21
- **Subtopics**:
  - `9.22.1` Momentum: exponential moving average of past gradients ($v_t = \beta v_{t-1} + g_t$); dampening oscillations in ravines
  - `9.22.2` Nesterov Accelerated Gradient (NAG): computing gradient after looking ahead along current momentum vector
  - `9.22.3` RMSprop: adaptive learning rates dividing gradient by root-mean-square of running squared gradients ($s_t = \beta s_{t-1} + (1-\beta)g_t^2$)
  - `9.22.4` Adam (Adaptive Moment Estimation): combining 1st moment (momentum) and 2nd moment (RMSprop) with bias correction for initial steps
  - `9.22.5` Adam bias correction derivation: why dividing by $(1 - \beta_1^t)$ and $(1 - \beta_2^t)$ is mathematically necessary near $t=1$
  - `9.22.6` AdamW (Decoupled Weight Decay): Loshchilov & Hutter''s proof that $L_2$ regularization $\neq$ weight decay in adaptive optimizers; AdamW formulation
- **Key Failure Modes & Edge Cases**: Using standard Adam with $L_2$ penalty instead of AdamW, causing heavily updated weights to decay slower than rarely updated weights.
- **Verification & Mastery Check**: Implement SGD with Momentum, RMSprop, and AdamW from scratch in pure NumPy; compare convergence trajectories on a Rosenbrock function.
- **Project Application**: GradFlow & TransformerLab: Production AdamW optimizer engine.', '{"solution.py": "# Phase 9 // Lesson 9.22: Advanced Optimizers: Momentum, Nesterov, RMSprop & AdamW\n\ndef solve():\n    \"\"\"\n    Verification: Implement SGD with Momentum, RMSprop, and AdamW from scratch in pure NumPy; compare convergence traj\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.22", "subtopics_count": 6, "verification_criteria": "Implement SGD with Momentum, RMSprop, and AdamW from scratch in pure NumPy; compare convergence trajectories on a Rosenbrock function.", "subtopics": ["9.22.1 Momentum: exponential moving average of past gradients ($v_t = \\beta v_{t-1} + g_t$); dampening oscillations in ravines", "9.22.2 Nesterov Accelerated Gradient (NAG): computing gradient after looking ahead along current momentum vector", "9.22.3 RMSprop: adaptive learning rates dividing gradient by root-mean-square of running squared gradients ($s_t = \\beta s_{t-1} + (1-\\beta)g_t^2$)", "9.22.4 Adam (Adaptive Moment Estimation): combining 1st moment (momentum) and 2nd moment (RMSprop) with bias correction for initial steps", "9.22.5 Adam bias correction derivation: why dividing by $(1 - \\beta_1^t)$ and $(1 - \\beta_2^t)$ is mathematically necessary near $t=1$", "9.22.6 AdamW (Decoupled Weight Decay): Loshchilov & Hutter''s proof that $L_2$ regularization $\\neq$ weight decay in adaptive optimizers; AdamW formulation"]}'::jsonb, '["Explain how this implementation prevents: Using standard Adam with $L_2$ penalty instead of AdamW, causing heavily updated weights to decay slower than rarely upd", "How does Advanced Optimizers: Momentum, Nesterov, RMSprop & AdamW scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-23', 'phase-09-lesson-23-learning-rate-schedulers-regularization-t', 'module-4', 23, 'Lesson 4.23: Learning Rate Schedulers & Regularization Techniques', 'Prerequisites: Lesson 9.22', 'Prerequisites: Lesson 9.22 | Subtopics: 6 items', 'Systems project application', 280, 10, 2370.0, 1150.0, '# Lesson 9.23: Learning Rate Schedulers & Regularization Techniques

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.22
- **Subtopics**:
  - `9.23.1` Learning rate scheduling: Step decay, Exponential decay, and Cosine Annealing schedules
  - `9.23.2` Linear Warmup: starting with small learning rate to prevent early unstable gradients from destroying pre-trained or initialized weights
  - `9.23.3` Cosine Annealing with Warmup: modern standard schedule in LLM pre-training ($T_{warmup}$, $T_{max}$, $\eta_{min}$)
  - `9.23.4` $L_2$ Regularization (Ridge / Weight Decay): shrinking weights toward zero, geometric interpretation as constraining parameter norm ball
  - `9.23.5` $L_1$ Regularization (Lasso): sparsity induction, geometric interpretation at coordinate corners
  - `9.23.6` Dropout: randomly zeroing activations with probability $p$ during training; inverted dropout scaling ($\frac{1}{1-p}$) to preserve inference expectation
- **Key Failure Modes & Edge Cases**: Failing to scale inverted dropout by $\frac{1}{1-p}$ during training, causing activation magnitudes to diverge between train and eval modes.
- **Verification & Mastery Check**: Implement Cosine Annealing with Warmup scheduler and Inverted Dropout from scratch; verify learning rate schedule curves.
- **Project Application**: TransformerLab: Training loop scheduler and regularization.', '{"solution.py": "# Phase 9 // Lesson 9.23: Learning Rate Schedulers & Regularization Techniques\n\ndef solve():\n    \"\"\"\n    Verification: Implement Cosine Annealing with Warmup scheduler and Inverted Dropout from scratch; verify learning \n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.23", "subtopics_count": 6, "verification_criteria": "Implement Cosine Annealing with Warmup scheduler and Inverted Dropout from scratch; verify learning rate schedule curves.", "subtopics": ["9.23.1 Learning rate scheduling: Step decay, Exponential decay, and Cosine Annealing schedules", "9.23.2 Linear Warmup: starting with small learning rate to prevent early unstable gradients from destroying pre-trained or initialized weights", "9.23.3 Cosine Annealing with Warmup: modern standard schedule in LLM pre-training ($T_{warmup}$, $T_{max}$, $\\eta_{min}$)", "9.23.4 $L_2$ Regularization (Ridge / Weight Decay): shrinking weights toward zero, geometric interpretation as constraining parameter norm ball", "9.23.5 $L_1$ Regularization (Lasso): sparsity induction, geometric interpretation at coordinate corners", "9.23.6 Dropout: randomly zeroing activations with probability $p$ during training; inverted dropout scaling ($\\frac{1}{1-p}$) to preserve inference expectation"]}'::jsonb, '["Explain how this implementation prevents: Failing to scale inverted dropout by $\\frac{1}{1-p}$ during training, causing activation magnitudes to diverge between t", "How does Learning Rate Schedulers & Regularization Techniques scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-24', 'phase-09-lesson-24-building-an-autograd-engine-i-the-value-n', 'module-4', 24, 'Lesson 4.24: Building an Autograd Engine I: The Value Node & Computational Graph', 'Prerequisites: Lesson 9.8, Lesson 9.17', 'Prerequisites: Lesson 9.8, Lesson 9.17 | Subtopics: 6 items', 'Systems project application', 280, 10, 2250.0, 1200.0, '# Lesson 9.24: Building an Autograd Engine I: The Value Node & Computational Graph

