('node-9-29', 'phase-09-lesson-29-pytorch-deep-dive-i-tensors-storage-strid', 'module-4', 29, 'Lesson 4.29: PyTorch Deep Dive I: Tensors, Storage, Strides & Memory Layouts', 'Prerequisites: Lesson 9.6, Phase 0', 'Prerequisites: Lesson 9.6, Phase 0 | Subtopics: 6 items', 'Systems project application', 280, 10, 2370.0, 1450.0, '# Lesson 9.29: PyTorch Deep Dive I: Tensors, Storage, Strides & Memory Layouts

